"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { AlertTriangle, ArrowRight, CalendarDays, CheckCircle2, ChevronRight, ClipboardList, Clock3, FolderKanban, Layers3, LayoutDashboard, ListTodo, LogOut, Menu, Pencil, Plus, Search, ShieldCheck, Target, Users, X } from "lucide-react";
import { RichDisplay, RichEditor } from "./rich-editor";
import { ProjectTimeline } from "./project-timeline";
import { ProjectDocuments } from "./project-documents";

type User = { id:string; email?:string; name:string; role:"coordinator"|"staff" };
type Project = { id:string; name:string; code:string; description:string; scope:string; objective:string; risks:string; budget:number; currency:string; group_id:string|null; status:string; created_at:string };
type Task = { id:string; project_id:string; title:string; description:string; assignee_id:string|null; status:string; priority:string; estimated_hours:number; estimate_value:number; estimate_unit:string; planned_start:string|null; planned_end:string|null; actual_start:string|null; actual_end:string|null; kind:string; stage_id:string|null; progress:number };
type Stage = { id:string; project_id:string; name:string; sort_order:number };
type Stakeholder = { id:string; project_id:string; name:string; organization:string; role:string; raci:string };
type Reschedule = { id:string; task_id:string; old_start:string|null; old_end:string|null; new_start:string|null; new_end:string|null; reason:string; changed_by:string; created_at:string };
type DependencySummary = { id:string; title:string; status:string };
type Data = { user:User; users:User[]; projects:Project[]; tasks:Task[]; members:{project_id:string;user_id:string}[]; groups:{id:string;name:string}[]; stages:Stage[]; stakeholders:Stakeholder[]; assignees:{task_id:string;user_id:string}[]; dependencies:{task_id:string;depends_on_id:string}[]; dependencyTasks:DependencySummary[]; reschedules:Reschedule[]; pending?:boolean; email?:string };
type Modal = "project"|"group"|"stage"|"stakeholder"|"task"|"taskManage"|"progress"|"member"|"assign"|null;
const statuses:Record<string,string> = {todo:"Por hacer",progress:"En progreso",review:"En revisión",done:"Completada"};
const projectStatuses:Record<string,{label:string;style:string}> = {
  pending:{label:"Pendiente",style:"bg-slate-100 text-slate-600"},
  in_progress:{label:"En curso",style:"bg-blue-100 text-blue-700"},
  standby:{label:"StandBy",style:"bg-amber-100 text-amber-800"},
  cancelled:{label:"Cancelado",style:"bg-red-100 text-red-700"},
  completed:{label:"Finalizado",style:"bg-green-100 text-green-700"},
};
const normalizeProjectStatus=(status:string)=>status==="planning"?"pending":status==="active"?"in_progress":status;
const sortByStart=(a:Task,b:Task)=>(a.planned_start||"9999-12-31").localeCompare(b.planned_start||"9999-12-31")||(a.planned_end||"9999-12-31").localeCompare(b.planned_end||"9999-12-31")||a.title.localeCompare(b.title,"es");
const afterDate=(date:string)=>{const next=new Date(`${date}T00:00:00Z`);next.setUTCDate(next.getUTCDate()+1);return next.toISOString().slice(0,10)};
const shiftDays=(date:string,days:number)=>{const next=new Date(`${date}T00:00:00Z`);next.setUTCDate(next.getUTCDate()+days);return next.toISOString().slice(0,10)};
const weekOf=(date:string)=>shiftDays(date,-((new Date(`${date}T00:00:00Z`).getUTCDay()+6)%7));
const raci:Record<string,string> = {R:"Responsable",A:"Aprobador",C:"Consultado",I:"Informado"};
const blank = {id:"",name:"",code:"",description:"",scope:"",objective:"",risks:"",budget:"0",currency:"PEN",projectId:"",groupId:"",title:"",kind:"activity",stageId:"",estimateValue:"8",estimateUnit:"hours",priority:"medium",plannedStart:"",plannedEnd:"",actualStart:"",actualEnd:"",progress:"0",status:"todo",reason:"",email:"",role:"staff",organization:"",roleName:"",raci:"I",userId:""};
const today = () => { const d=new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`; };
const fmt = (d:string|null|undefined) => d ? new Date(`${d}T12:00:00`).toLocaleDateString("es-PE",{day:"2-digit",month:"short",year:"numeric"}) : "—";
const initials = (s:string) => s.trim().split(/\s+/).slice(0,2).map(x=>x[0]).join("").toUpperCase();
const delayed = (t:Task) => t.status!=="done" && !!t.planned_end && t.planned_end<today();
const estimateLabel = (t:Task) => { const n=t.estimate_value||t.estimated_hours||0; return `${n} ${t.estimate_unit==="days"?(n===1?"día":"días"):(n===1?"hora":"horas")}`; };

export default function Dashboard() {
  const [data,setData]=useState<Data|null>(null),[loading,setLoading]=useState(true),[error,setError]=useState("");
  const [tab,setTab]=useState("overview"),[projectTab,setProjectTab]=useState("activities"),[selected,setSelected]=useState("");
  const [modal,setModal]=useState<Modal>(null),[form,setForm]=useState<Record<string,string>>(blank),[selectedAssignees,setSelectedAssignees]=useState<string[]>([]),[selectedDependencies,setSelectedDependencies]=useState<string[]>([]);
  const [profileEditing,setProfileEditing]=useState(false),[profileDraft,setProfileDraft]=useState<Record<string,string>>({});
  const [saving,setSaving]=useState(false),[search,setSearch]=useState(""),[filter,setFilter]=useState("all"),[taskProjectFilter,setTaskProjectFilter]=useState("all"),[weekStart,setWeekStart]=useState(()=>weekOf(today())),[projectStatusFilter,setProjectStatusFilter]=useState("all"),[projectGroupFilter,setProjectGroupFilter]=useState("all"),[mobile,setMobile]=useState(false);
  const load=useCallback(async()=>{try{const r=await fetch("/api/workspace",{cache:"no-store"});const j=await r.json() as Data&{error?:string};if(!r.ok)throw new Error(j.error||"No se pudieron cargar los datos");setData(j);setError("")}catch(e){setError(e instanceof Error?e.message:"Error de carga")}finally{setLoading(false)}},[]);
  useEffect(()=>{load()},[load]);
  const projects=data?.projects||[], tasks=data?.tasks||[], users=data?.users||[], stages=data?.stages||[], stakeholders=data?.stakeholders||[], groups=data?.groups||[];
  const isCoordinator=data?.user.role==="coordinator";
  const project=projects.find(p=>p.id===selected);
  const progress=(pid:string)=>{const own=tasks.filter(t=>t.project_id===pid);return own.length?Math.round(own.reduce((n,t)=>n+t.progress,0)/own.length):0};
  const visibleTasks=tasks.filter(t=>(taskProjectFilter==="all"||t.project_id===taskProjectFilter)&&(filter==="all"||t.status===filter)&&(!search||`${t.title} ${projects.find(p=>p.id===t.project_id)?.name||""}`.toLowerCase().includes(search.toLowerCase())));
  const weekEnd=shiftDays(weekStart,6);
  const weeklyTasks=visibleTasks.filter(t=>!!t.planned_start&&!!t.planned_end&&t.planned_start<=weekEnd&&t.planned_end>=weekStart);
  const visibleProjects=projects.filter(p=>`${p.name} ${p.code}`.toLowerCase().includes(search.toLowerCase())&&(projectStatusFilter==="all"||normalizeProjectStatus(p.status)===projectStatusFilter)&&(projectGroupFilter==="all"||(p.group_id||"")===projectGroupFilter));
  const dependentTasks=selectedDependencies.map(id=>tasks.find(t=>t.id===id)).filter((t):t is Task=>!!t);
  const dependencyStart=selectedDependencies.length&&dependentTasks.length===selectedDependencies.length&&dependentTasks.every(t=>!!t.planned_end)
    ?afterDate(dependentTasks.map(t=>t.planned_end!).sort().at(-1)!):"";
  useEffect(()=>{if((modal==="task"||modal==="taskManage")&&dependencyStart){setForm(old=>old.plannedStart===dependencyStart?old:{...old,plannedStart:dependencyStart,plannedEnd:old.plannedEnd&&old.plannedEnd<dependencyStart?dependencyStart:old.plannedEnd})}},[dependencyStart,modal]);
  const upcoming=useMemo(()=>tasks.filter(t=>t.status!=="done"&&t.planned_end).sort((a,b)=>(a.planned_end||"").localeCompare(b.planned_end||"")).slice(0,5),[tasks]);
  const open=(type:Modal,values:Record<string,string>={},assignees:string[]=[],dependencies:string[]=[])=>{setForm({...blank,...values});setSelectedAssignees(assignees);setSelectedDependencies(dependencies);setError("");setModal(type)};
  const update=(key:string,value:string)=>setForm(v=>({...v,[key]:value}));
  const goto=(key:string)=>{setTab(key);setMobile(false);setSearch("");setFilter("all")};
  const post=async(operation:string,payload:Record<string,unknown>)=>{const r=await fetch("/api/workspace",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({operation,...payload})});const j=await r.json() as {error?:string};if(!r.ok)throw new Error(j.error||"No se pudo guardar")};
  const save=async(operation:string)=>{setSaving(true);setError("");try{await post(operation,{...form,assigneeIds:selectedAssignees,dependencyIds:selectedDependencies});setModal(null);await load()}catch(e){setError(e instanceof Error?e.message:"No se pudo guardar")}finally{setSaving(false)}};
  const startProfileEdit=(item:Project)=>{setProfileDraft({id:item.id,description:item.description||"",scope:item.scope||"",objective:item.objective||"",risks:item.risks||"",budget:String((item.budget||0)/100),currency:item.currency||"PEN"});setProjectTab("profile");setProfileEditing(true);setError("")};
  const updateProfile=(key:string,value:string)=>setProfileDraft(old=>({...old,[key]:value}));
  const saveProfile=async()=>{setSaving(true);setError("");try{await post("projectProfile",profileDraft);await load();setProfileEditing(false)}catch(e){setError(e instanceof Error?e.message:"No se pudo guardar la ficha")}finally{setSaving(false)}};
  const changeGroup=async(projectId:string,groupId:string)=>{try{await post("projectGroup",{projectId,groupId});await load()}catch(e){setError(e instanceof Error?e.message:"No se pudo cambiar el grupo")}};
  const changeStatus=async(id:string,status:string)=>{try{await post("projectStatus",{id,status});await load()}catch(e){setError(e instanceof Error?e.message:"No se pudo actualizar")}};
  const openProject=(id:string)=>{setSelected(id);setProjectTab("activities");setProfileEditing(false);goto("project")};
  const openTask=(t:Task,manage=false)=>open(manage?"taskManage":"progress",{id:t.id,projectId:t.project_id,title:t.title,description:t.description,kind:t.kind||"activity",stageId:t.stage_id||"",estimateValue:String(t.estimate_value||t.estimated_hours||0),estimateUnit:t.estimate_unit||"hours",priority:t.priority,plannedStart:t.planned_start||"",plannedEnd:t.planned_end||"",actualStart:t.actual_start||"",actualEnd:t.actual_end||"",status:t.status,progress:String(t.progress)},data?.assignees.filter(a=>a.task_id===t.id).map(a=>a.user_id)||[t.assignee_id||""],data?.dependencies.filter(d=>d.task_id===t.id).map(d=>d.depends_on_id)||[]);
  const assigneeNames=(t:Task)=>{const ids=data?.assignees.filter(a=>a.task_id===t.id).map(a=>a.user_id)||[];if(!ids.length&&t.assignee_id)ids.push(t.assignee_id);return ids.map(id=>users.find(u=>u.id===id)?.name||"Personal").join(", ")||"Sin asignar"};
  const blockers=(t:Task)=>data?.dependencies.filter(d=>d.task_id===t.id).map(d=>data.dependencyTasks.find(other=>other.id===d.depends_on_id)).filter((other):other is DependencySummary=>!!other&&other.status!=="done")||[];
  const taskBoard=(items:Task[])=>{
    const sorted=[...items].sort(sortByStart);
    const projectIds=[...new Set(sorted.map(t=>t.project_id))];
    const buckets=projectIds.flatMap(pid=>[...stages.filter(s=>s.project_id===pid).map(s=>({key:s.id,title:`${projects.find(p=>p.id===pid)?.name} · ${s.name}`,items:sorted.filter(t=>t.project_id===pid&&t.stage_id===s.id)})),{key:`none-${pid}`,title:"",items:sorted.filter(t=>t.project_id===pid&&!t.stage_id)}]).filter(b=>b.items.length);
    buckets.sort((a,b)=>sortByStart(a.items[0],b.items[0]));
    return buckets.length?<div className="space-y-6">{buckets.map(b=><section key={b.key}>{b.title&&<div className="mb-3 flex items-center gap-2"><Layers3 size={15} className="text-[#3b75a4]"/><h3 className="text-sm font-bold text-[#173d60]">{b.title}</h3><span className="rounded-full bg-[#e8f2fa] px-2 py-0.5 text-[10px] font-semibold text-[#346f9e]">{b.items.length}</span></div>}<TaskList items={b.items} {...{projects,stages,assigneeNames,openTask,isCoordinator,blockers}}/></section>)}</div>:<Empty text="Aún no hay actividades"/>;
  };
  if(loading)return <div className="flex min-h-screen items-center justify-center bg-[#f5f9fd] text-sm text-[#5a7b98]">Cargando espacio de trabajo…</div>;
  if(data?.pending)return <div className="flex min-h-screen items-center justify-center bg-[#f5f9fd] p-6"><div className="max-w-md rounded-2xl bg-white p-10 text-center shadow-sm"><ShieldCheck className="mx-auto mb-5 text-[#377cad]" size={38}/><h1 className="text-2xl font-bold text-[#133a5c]">Acceso pendiente</h1><p className="mt-3 text-sm leading-6 text-[#6b859c]">Solicita al coordinador que registre <strong>{data.email}</strong> en el equipo.</p></div></div>;
  if(!data)return <div className="p-10 text-red-600">{error} <button className="underline" onClick={load}>Reintentar</button></div>;
  return <div className="min-h-screen bg-[#f5f9fd] text-[#183a58]">
    <aside className={`fixed inset-y-0 left-0 z-40 flex w-[252px] flex-col bg-[#0e3455] text-white transition-transform lg:translate-x-0 ${mobile?"translate-x-0":"-translate-x-full"}`}>
      <div className="flex h-[80px] items-center gap-3 border-b border-white/10 px-6"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#3186c1] text-xl font-extrabold">N</div><div><div className="text-xl font-bold tracking-tight">nexo<span className="text-[#74c1ef]">.</span></div><div className="-mt-1 text-[10px] tracking-[.14em] text-[#91b9d7]">PROJECT WORKSPACE</div></div><button className="ml-auto lg:hidden" onClick={()=>setMobile(false)} aria-label="Cerrar menú"><X size={18}/></button></div>
      <nav className="px-4 pt-7"><p className="mb-3 px-3 text-[10px] font-bold uppercase tracking-[.18em] text-[#79a6c7]">Espacio de trabajo</p>{([["overview",LayoutDashboard,"Resumen"],["projects",FolderKanban,"Proyectos"],["tasks",ListTodo,"Actividades"],["team",Users,"Equipo"]] as const).filter(([key])=>key!=="team"||isCoordinator).map(([key,Icon,label])=><button key={key} onClick={()=>goto(key)} className={`mb-1 flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-sm ${tab===key||(tab==="project"&&key==="projects")?"bg-[#27577c] font-semibold":"text-[#abc9dd] hover:bg-white/5 hover:text-white"}`}><Icon size={18}/>{label}{key==="tasks"&&<span className="ml-auto rounded-md bg-white/10 px-2 text-[11px]">{tasks.length}</span>}</button>)}</nav>
      <div className="mt-8 px-4"><div className="flex items-center justify-between px-3"><p className="text-[10px] font-bold uppercase tracking-[.18em] text-[#79a6c7]">Proyectos</p>{isCoordinator&&<button onClick={()=>open("project")} aria-label="Nuevo proyecto"><Plus size={16}/></button>}</div><div className="mt-3 max-h-56 overflow-auto">{projects.slice(0,7).map(p=><button key={p.id} onClick={()=>openProject(p.id)} className="flex w-full items-center gap-3 rounded-lg px-3 py-2 text-left text-xs text-[#abc9dd] hover:bg-white/5 hover:text-white"><span className="h-2 w-2 shrink-0 rounded-full bg-[#6eb6e5]"/><span className="truncate">{p.name}</span></button>)}</div></div>
      <div className="mt-auto border-t border-white/10 p-4"><div className="flex items-center gap-3 p-2"><Avatar name={data.user.name}/><div className="min-w-0 flex-1"><p className="truncate text-xs font-semibold">{data.user.name}</p><p className="text-[11px] text-[#91b9d7]">{isCoordinator?"Coordinador":"Personal"}</p></div><a href="/signout-with-chatgpt?return_to=/" target="_top" aria-label="Cerrar sesión" className="text-[#91b9d7]"><LogOut size={16}/></a></div></div>
    </aside>
    {mobile&&<button onClick={()=>setMobile(false)} className="fixed inset-0 z-30 bg-[#08253d]/60 lg:hidden" aria-label="Cerrar menú"/>}
    <div className="lg:ml-[252px]"><header className="flex h-[80px] items-center justify-between border-b border-[#dce8f1] bg-white px-5 md:px-9"><div className="flex items-center gap-4"><button className="lg:hidden" onClick={()=>setMobile(true)} aria-label="Abrir menú"><Menu size={21}/></button><div className="hidden items-center gap-2 text-xs text-[#8aa4b9] sm:flex">Espacio de trabajo <ChevronRight size={13}/><strong className="font-medium text-[#38627f]">{tab==="project"?project?.name:({overview:"Resumen",projects:"Proyectos",tasks:"Actividades",team:"Equipo"} as Record<string,string>)[tab]}</strong></div></div><div className="flex items-center gap-4"><span className="hidden text-xs text-[#7895aa] sm:block"><CalendarDays size={14} className="mr-2 inline"/>{new Date().toLocaleDateString("es-PE",{day:"numeric",month:"long",year:"numeric"})}</span><Avatar name={data.user.name}/></div></header>
      <main className="mx-auto max-w-[1440px] px-5 pb-16 pt-8 md:px-9">
        {tab==="overview"&&<>
          <Heading eyebrow="Panel de control" title={`Buenos días, ${data.user.name.split(" ")[0]}`} subtitle="Una visión clara de tus proyectos y próximas entregas." action={isCoordinator?()=>open("project"):undefined} actionText="Nuevo proyecto"/>
          <div className="mb-7 grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{([["Proyectos activos",projects.filter(p=>normalizeProjectStatus(p.status)==="in_progress").length,FolderKanban],["Actividades en curso",tasks.filter(t=>t.status==="progress").length,Clock3],["Completadas",tasks.filter(t=>t.status==="done").length,CheckCircle2]] as const).map(([label,n,Icon])=><div key={label} className="panel p-5"><div className="mb-5 flex justify-between"><span className="text-xs text-[#6987a0]">{label}</span><span className="rounded-xl bg-[#e8f3fb] p-2.5 text-[#2875ab]"><Icon size={18}/></span></div><strong className="text-3xl text-[#143d61]">{n}</strong></div>)}</div>
          {tasks.some(delayed)&&<div className="mb-7 flex items-center gap-3 rounded-xl border border-[#f1c5c5] bg-[#fff2f2] px-5 py-4 text-sm text-[#a64a4a]"><AlertTriangle size={18}/><span><strong>{tasks.filter(delayed).length} actividades retrasadas.</strong> Revisa sus fechas planificadas o registra el avance.</span><button onClick={()=>goto("tasks")} className="ml-auto font-semibold underline">Ver</button></div>}
          <div className="grid gap-6 xl:grid-cols-[1.5fr_1fr]"><section className="panel p-6"><div className="mb-5 flex justify-between"><div><h2 className="text-lg font-bold">Proyectos recientes</h2><p className="text-xs text-[#88a1b7]">Seguimiento del portafolio</p></div><button onClick={()=>goto("projects")} className="text-xs font-semibold text-[#2d76a8]">Ver todos <ArrowRight size={13} className="inline"/></button></div>{projects.length?<div className="space-y-3">{projects.slice(0,4).map(p=><button key={p.id} onClick={()=>openProject(p.id)} className="flex w-full items-center gap-4 rounded-xl border border-[#e6eef5] p-4 text-left hover:bg-[#f8fbfe]"><span className="flex h-11 w-11 items-center justify-center rounded-xl bg-[#e8f3fb] text-sm font-bold text-[#3678a5]">{initials(p.name)}</span><span className="min-w-0 flex-1"><strong className="block truncate text-sm">{p.name}</strong><small className="text-[#8ba5b8]">{p.code} · {groups.find(g=>g.id===p.group_id)?.name||"Sin grupo"}</small></span><strong className="text-xs text-[#42799f]">{progress(p.id)}%</strong><ChevronRight size={16} className="text-[#abc3d4]"/></button>)}</div>:<Empty text="Aún no hay proyectos"/>}</section><section className="panel p-6"><h2 className="text-lg font-bold">Próximas entregas</h2><p className="mb-5 text-xs text-[#88a1b7]">Ordenadas por fecha planificada</p>{upcoming.length?upcoming.map(t=><button key={t.id} onClick={()=>{goto("tasks");setWeekStart(weekOf(t.planned_end||t.planned_start||today()));setSearch(t.title)}} className="flex w-full items-center gap-3 border-b border-[#edf3f7] py-3 text-left last:border-0"><span className={`rounded-lg px-2 py-2 text-xs font-bold ${delayed(t)?"bg-red-50 text-red-600":"bg-[#e8f3fb] text-[#3678a5]"}`}>{fmt(t.planned_end)}</span><span className="min-w-0"><strong className="block truncate text-xs">{t.title}</strong><small className="text-[#91aabc]">{projects.find(p=>p.id===t.project_id)?.name}</small></span></button>):<Empty text="No hay próximas entregas"/>}</section></div>
        </>}
        {tab==="projects"&&<>
          <Heading eyebrow="Portafolio" title="Proyectos" subtitle="Consulta el estado y avance de tus proyectos." action={isCoordinator?()=>open("project"):undefined} actionText="Nuevo proyecto"/>
          <div className="mb-6 flex flex-wrap items-center gap-2 lg:flex-nowrap"><SearchBox value={search} onChange={setSearch} placeholder="Buscar proyectos..."/><select className="field compact-filter w-[145px] shrink-0" aria-label="Filtrar por estado" value={projectStatusFilter} onChange={e=>setProjectStatusFilter(e.target.value)}><option value="all">Todos los estados</option>{Object.entries(projectStatuses).map(([key,item])=><option key={key} value={key}>{item.label}</option>)}</select><select className="field compact-filter w-[145px] shrink-0" aria-label="Filtrar por grupo" value={projectGroupFilter} onChange={e=>setProjectGroupFilter(e.target.value)}><option value="all">Todos los grupos</option><option value="">Sin grupo</option>{groups.map(g=><option key={g.id} value={g.id}>{g.name}</option>)}</select>{isCoordinator&&<button className="secondary-btn shrink-0" onClick={()=>open("group")}><Plus size={15}/> Crear grupo</button>}</div>
          {error&&<Notice text={error}/>}
          {visibleProjects.length?<ProjectCards items={visibleProjects} {...{progress,groups,openProject}}/>:<Empty text={projects.length?"No hay proyectos para estos filtros":"Aún no hay proyectos"}/>}
        </>}
        {tab==="project"&&project&&<>
          <button onClick={()=>goto("projects")} className="mb-5 text-xs font-semibold text-[#397ca9]">← Volver a proyectos</button><div className="mb-6 flex flex-wrap items-start justify-between gap-4"><div><div className="mb-2 flex items-center gap-2"><span className="rounded-lg bg-[#e8f2fa] px-2 py-1 text-[11px] font-bold text-[#3274a2]">{project.code}</span><ProjectStatus value={project.status}/></div><h1 className="text-3xl font-bold uppercase tracking-tight text-[#133a5c]">{project.name}</h1></div><div className="flex gap-2">{isCoordinator&&<button className="secondary-btn" onClick={()=>startProfileEdit(project)}><Pencil size={15}/> Editar ficha</button>}{isCoordinator&&<button className="primary-btn" onClick={()=>open("task",{projectId:project.id})}><Plus size={16}/> Nueva actividad</button>}</div></div>
          {isCoordinator&&<div className="mb-5 flex items-center gap-3"><label className="text-xs font-semibold text-[#6387a1]" htmlFor="project-status">Estado del proyecto</label><select id="project-status" className="field w-auto" value={normalizeProjectStatus(project.status)} onChange={e=>changeStatus(project.id,e.target.value)}>{Object.entries(projectStatuses).map(([key,item])=><option key={key} value={key}>{item.label}</option>)}</select></div>}
          <div className="mb-6 flex flex-wrap gap-2 border-b border-[#dce8f1]">{[["activities","Actividades"],["timeline","Línea de tiempo"],["profile","Ficha del proyecto"],["documents","Documentos"],["stakeholders","Interesados · RACI"],["team","Equipo"]].map(([key,label])=><button key={key} onClick={()=>setProjectTab(key)} className={`border-b-2 px-4 py-3 text-sm font-semibold ${projectTab===key?"border-[#2b7fb8] text-[#1f6599]":"border-transparent text-[#7c9aaf]"}`}>{label}</button>)}</div>
          {projectTab==="activities"&&<><div className="mb-5 flex flex-wrap items-center gap-3">{isCoordinator&&<button className="secondary-btn" onClick={()=>open("stage",{projectId:project.id})}><Plus size={15}/> Nueva etapa</button>}<span className="ml-auto text-xs text-[#8ba4b8]">{tasks.filter(t=>t.project_id===project.id).length} actividades</span></div>{taskBoard(tasks.filter(t=>t.project_id===project.id))}</>}
          {projectTab==="timeline"&&<><div className="mb-4"><h2 className="text-lg font-bold text-[#173d60]">Línea de tiempo</h2><p className="mt-1 text-xs text-[#7896ac]">Fechas planificadas y reales de actividades e hitos. Desplázate horizontalmente para ver todo el periodo.</p></div><ProjectTimeline tasks={tasks.filter(t=>t.project_id===project.id)} stages={stages.filter(s=>s.project_id===project.id)}/></>}
          {projectTab==="documents"&&<ProjectDocuments key={project.id} projectId={project.id}/>}
          {projectTab==="profile"&&<div className="max-w-4xl">
            {profileEditing&&isCoordinator? <form onSubmit={e=>{e.preventDefault();saveProfile()}} className="space-y-6">
              <div className="flex flex-wrap items-center justify-between gap-3 border-b border-[#dce8f1] pb-5"><div><h2 className="text-lg font-bold text-[#173d60]">Editar ficha del proyecto</h2><p className="mt-1 text-xs text-[#7896ac]">Documenta los datos del proyecto directamente en esta vista.</p></div><div className="flex gap-2"><button type="button" className="secondary-btn" onClick={()=>{setProfileEditing(false);setError("")}}>Cancelar</button><button type="submit" className="primary-btn" disabled={saving}>{saving?"Guardando…":"Guardar ficha"}</button></div></div>
              <RichEditor key={`${project.id}-description`} label="Descripción" value={profileDraft.description||""} onChange={value=>updateProfile("description",value)}/>
              <RichEditor key={`${project.id}-scope`} label="Alcance" value={profileDraft.scope||""} onChange={value=>updateProfile("scope",value)}/>
              <RichEditor key={`${project.id}-objective`} label="Objetivos" value={profileDraft.objective||""} onChange={value=>updateProfile("objective",value)}/>
              <RichEditor key={`${project.id}-risks`} label="Riesgos" value={profileDraft.risks||""} onChange={value=>updateProfile("risks",value)}/>
              <div className="grid max-w-md grid-cols-[1fr_130px] gap-3"><Field label="Presupuesto"><input className="field" type="number" min="0" step="0.01" value={profileDraft.budget||"0"} onChange={e=>updateProfile("budget",e.target.value)}/></Field><Field label="Moneda"><select className="field" value={profileDraft.currency||"PEN"} onChange={e=>updateProfile("currency",e.target.value)}><option value="PEN">PEN</option><option value="USD">USD</option><option value="EUR">EUR</option></select></Field></div>
              {error&&<Notice text={error}/>}<div className="flex justify-end gap-2 border-t border-[#dce8f1] pt-5"><button type="button" className="secondary-btn" onClick={()=>{setProfileEditing(false);setError("")}}>Cancelar</button><button type="submit" className="primary-btn" disabled={saving}>{saving?"Guardando…":"Guardar ficha"}</button></div>
            </form>:<><div className="flex justify-end">{isCoordinator&&<button className="secondary-btn" onClick={()=>startProfileEdit(project)}><Pencil size={15}/> Editar ficha</button>}</div><div className="divide-y divide-[#dce8f1]">{([["Descripción",project.description],["Alcance",project.scope],["Objetivos",project.objective],["Riesgos",project.risks]] as const).map(([label,value])=><section key={label} className="grid gap-2 py-5 md:grid-cols-[170px_1fr]"><h2 className="text-xs font-bold uppercase tracking-wide text-[#6888a1]">{label}</h2><div className="text-sm leading-6 text-[#214968]"><RichDisplay value={value||""}/></div></section>)}<section className="grid gap-2 py-5 md:grid-cols-[170px_1fr]"><h2 className="text-xs font-bold uppercase tracking-wide text-[#6888a1]">Presupuesto</h2><p className="text-sm font-semibold">{new Intl.NumberFormat("es-PE",{style:"currency",currency:project.currency||"PEN"}).format((project.budget||0)/100)}</p></section><section className="grid gap-2 py-5 md:grid-cols-[170px_1fr]"><h2 className="text-xs font-bold uppercase tracking-wide text-[#6888a1]">Grupo</h2>{isCoordinator?<select className="field max-w-xs" aria-label="Grupo del proyecto" value={project.group_id||""} onChange={e=>changeGroup(project.id,e.target.value)}><option value="">Sin grupo</option>{groups.map(g=><option key={g.id} value={g.id}>{g.name}</option>)}</select>:<p className="text-sm">{groups.find(g=>g.id===project.group_id)?.name||"Sin grupo"}</p>}</section></div></>}
          </div>}
          {projectTab==="stakeholders"&&<><div className="mb-5 flex flex-wrap items-center justify-between gap-3"><p className="text-sm text-[#6a88a0]">Clasifica a cada interesado por su participación en el proyecto.</p>{isCoordinator&&<button className="primary-btn" onClick={()=>open("stakeholder",{projectId:project.id})}><Plus size={15}/> Agregar interesado</button>}</div><div className="mb-5 flex flex-wrap gap-2">{Object.entries(raci).map(([key,label])=><span key={key} className="rounded-lg bg-[#eaf3fa] px-3 py-1.5 text-xs text-[#376e96]"><strong>{key}</strong> · {label}</span>)}</div><div className="grid gap-3 md:grid-cols-2">{stakeholders.filter(s=>s.project_id===project.id).map(s=><button key={s.id} onClick={()=>isCoordinator&&open("stakeholder",{id:s.id,projectId:s.project_id,name:s.name,organization:s.organization,roleName:s.role,raci:s.raci})} className="panel flex items-center gap-4 p-5 text-left"><Avatar name={s.name}/><span className="min-w-0 flex-1"><strong className="block truncate text-sm">{s.name}</strong><small className="text-[#8ba4b8]">{[s.role,s.organization].filter(Boolean).join(" · ")||"Interesado"}</small></span><span className="rounded-lg bg-[#dceefb] px-3 py-1 text-xs font-bold text-[#2d6f9f]">{s.raci}</span></button>)}</div>{!stakeholders.some(s=>s.project_id===project.id)&&<Empty text="Aún no se han registrado interesados"/>}</>}
          {projectTab==="team"&&<><div className="mb-5 flex justify-end">{isCoordinator&&<button className="primary-btn" onClick={()=>open("assign",{projectId:project.id})}><Plus size={15}/> Agregar integrante</button>}</div><div className="grid gap-3 md:grid-cols-2">{data.members.filter(m=>m.project_id===project.id).map(m=>{const u=users.find(u=>u.id===m.user_id);return u?<div key={m.user_id} className="panel flex items-center gap-3 p-4"><Avatar name={u.name}/><div><strong className="text-sm">{u.name}</strong><p className="text-xs text-[#8ba4b8]">{u.role==="coordinator"?"Coordinador":"Personal"}</p></div></div>:null})}</div>{!data.members.some(m=>m.project_id===project.id)&&<Empty text="Todavía no hay integrantes asignados"/>}</>}
        </>}
        {tab==="tasks"&&<><Heading eyebrow="Seguimiento" title="Actividades e hitos" subtitle="Revisa el trabajo planificado por semana, con responsables, avance y alertas." actionText=""/><div className="mb-5 flex flex-wrap items-center gap-2 lg:flex-nowrap"><SearchBox value={search} onChange={setSearch} placeholder="Buscar actividades..."/><select className="field compact-filter w-[150px] shrink-0" aria-label="Filtrar actividades por estado" value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">Todos los estados</option>{["todo","progress","review","done"].map(s=><option key={s} value={s}>{statuses[s]}</option>)}</select><select className="field compact-filter w-[190px] shrink-0" aria-label="Filtrar actividades por proyecto" value={taskProjectFilter} onChange={e=>setTaskProjectFilter(e.target.value)}><option value="all">Todos los proyectos</option>{projects.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></div><div className="mb-5 flex flex-wrap items-center justify-between gap-3 rounded-xl border border-[#dce8f1] bg-white px-4 py-3"><div><p className="text-[10px] font-bold uppercase tracking-[.16em] text-[#75a0bd]">Semana planificada</p><h2 className="mt-1 text-sm font-bold text-[#214968]">{fmt(weekStart)} – {fmt(weekEnd)}</h2><p className="mt-1 text-[11px] text-[#8ba5b8]">{weeklyTasks.length} {weeklyTasks.length===1?"actividad":"actividades"} en esta semana</p></div><div className="flex flex-wrap items-center gap-2"><button className="secondary-btn px-3 py-2" onClick={()=>setWeekStart(old=>shiftDays(old,-7))} aria-label="Semana anterior"><ChevronRight size={16} className="rotate-180"/></button><button className="secondary-btn px-3 py-2" onClick={()=>setWeekStart(weekOf(today()))}>Esta semana</button><button className="secondary-btn px-3 py-2" onClick={()=>setWeekStart(old=>shiftDays(old,7))} aria-label="Semana siguiente"><ChevronRight size={16}/></button><input className="field w-[145px]" type="date" aria-label="Ir a la semana de la fecha" value={weekStart} onChange={e=>e.target.value&&setWeekStart(weekOf(e.target.value))}/></div></div>{weeklyTasks.length?taskBoard(weeklyTasks):<Empty text="No hay actividades planificadas para esta semana"/>}</>}
        {tab==="team"&&isCoordinator&&<><Heading eyebrow="Colaboración" title="Equipo" subtitle="Registra personal y administra los roles." action={()=>open("member")} actionText="Agregar persona"/><div className="panel overflow-hidden"><div className="grid grid-cols-[1fr_130px_100px] border-b border-[#e6eef5] px-6 py-4 text-[11px] font-bold uppercase tracking-wider text-[#8ba5ba]"><span>Persona</span><span>Rol</span><span>Proyectos</span></div>{users.map(u=><div key={u.id} className="grid grid-cols-[1fr_130px_100px] items-center border-b border-[#edf2f7] px-6 py-4 last:border-0"><div className="flex min-w-0 items-center gap-3"><Avatar name={u.name}/><span className="min-w-0"><strong className="block truncate text-sm">{u.name}</strong><small className="block truncate text-xs text-[#8ba4b8]">{u.email}</small></span></div>{u.id===data.user.id?<span className="text-xs text-[#6c8ca5]">Coordinador</span>:<select className="field w-[118px]" value={u.role} onChange={async e=>{try{await post("role",{id:u.id,role:e.target.value});await load()}catch(x){setError(x instanceof Error?x.message:"Error")}}}><option value="staff">Personal</option><option value="coordinator">Coordinador</option></select>}<span className="text-xs text-[#6c8ca5]">{data.members.filter(m=>m.user_id===u.id).length}</span></div>)}</div></>}
      </main></div>
    {modal&&<div className="fixed inset-0 z-50 flex items-center justify-center bg-[#082944]/65 p-4" onMouseDown={e=>{if(e.target===e.currentTarget)setModal(null)}}><div className="max-h-[93vh] w-full max-w-[610px] overflow-y-auto rounded-2xl bg-white shadow-2xl"><div className="sticky top-0 z-10 flex items-center justify-between border-b border-[#e6eef5] bg-white px-6 py-5"><div><p className="text-[10px] font-bold uppercase tracking-[.18em] text-[#4387b4]">Espacio de trabajo</p><h2 className="mt-1 text-xl font-bold">{{project:"Nuevo proyecto",group:"Nuevo grupo",stage:"Nueva etapa",stakeholder:form.id?"Editar interesado":"Nuevo interesado",task:"Nueva actividad o hito",taskManage:"Editar actividad",progress:"Actualizar avance",member:"Agregar persona",assign:"Agregar integrante"}[modal]}</h2></div><button onClick={()=>setModal(null)} aria-label="Cerrar" className="rounded-lg p-2 text-[#8ca9bd] hover:bg-[#f1f6fa]"><X size={18}/></button></div>
      <form onSubmit={e=>{e.preventDefault();save(({project:"project",group:"group",stage:"stage",stakeholder:"stakeholder",task:"task",taskManage:"taskManage",progress:"taskProgress",member:"member",assign:"assignMember"} as Record<string,string>)[modal])}} className="space-y-4 p-6">
        {modal==="project"&&<><Field label="Nombre del proyecto *"><input className="field" required value={form.name} onChange={e=>update("name",e.target.value)} placeholder="Ej. Transformación digital"/></Field><Field label="Código para identificarlo *"><input className="field" required value={form.code} onChange={e=>update("code",e.target.value)} placeholder="PROY-001"/></Field><p className="hint">Después de crearlo podrás completar su ficha, definir etapas e incorporar interesados.</p></>}
        {modal==="group"&&<Field label="Nombre del grupo *"><input className="field" required value={form.name} onChange={e=>update("name",e.target.value)} placeholder="Ej. Proyectos estratégicos"/></Field>}
        {modal==="stage"&&<Field label="Nombre de la etapa *"><input className="field" required value={form.name} onChange={e=>update("name",e.target.value)} placeholder="Ej. Diagnóstico"/></Field>}
        {modal==="stakeholder"&&<><Field label="Nombre del interesado *"><input className="field" required value={form.name} onChange={e=>update("name",e.target.value)}/></Field><div className="grid grid-cols-2 gap-3"><Field label="Organización"><input className="field" value={form.organization} onChange={e=>update("organization",e.target.value)}/></Field><Field label="Cargo o función"><input className="field" value={form.roleName} onChange={e=>update("roleName",e.target.value)}/></Field></div><Field label="Clasificación RACI"><select className="field" value={form.raci} onChange={e=>update("raci",e.target.value)}>{Object.entries(raci).map(([key,label])=><option key={key} value={key}>{key} · {label}</option>)}</select></Field></>}
        {(modal==="task"||modal==="taskManage")&&<><p className="hint">Proyecto: <strong>{projects.find(p=>p.id===form.projectId)?.name||"Proyecto actual"}</strong></p><Field label="Nombre *"><input className="field" required value={form.title} onChange={e=>update("title",e.target.value)} placeholder="Ej. Aprobar diseño"/></Field><div className="grid grid-cols-2 gap-3"><Field label="Tipo"><select className="field" value={form.kind} onChange={e=>update("kind",e.target.value)}><option value="activity">Actividad</option><option value="milestone">Hito</option></select></Field><Field label="Etapa (opcional)"><select className="field" value={form.stageId} onChange={e=>update("stageId",e.target.value)}><option value="">Ninguna</option>{stages.filter(s=>s.project_id===form.projectId).map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></Field></div><Field label="Descripción"><textarea className="field min-h-16" value={form.description} onChange={e=>update("description",e.target.value)}/></Field><div><p className="mb-2 text-xs font-semibold text-[#3f617b]">Responsables * <span className="font-normal text-[#8aa6ba]">(uno o más)</span></p><div className="max-h-36 overflow-auto rounded-xl border border-[#dce8f1] p-3">{users.map(u=><label key={u.id} className="flex cursor-pointer items-center gap-2 rounded-lg px-2 py-1.5 text-xs hover:bg-[#f2f8fc]"><input type="checkbox" checked={selectedAssignees.includes(u.id)} onChange={e=>setSelectedAssignees(old=>e.target.checked?[...old,u.id]:old.filter(x=>x!==u.id))} className="accent-[#2d7eb4]"/>{u.name}</label>)}</div></div><div className="grid grid-cols-2 gap-3"><Field label="Prioridad"><select className="field" value={form.priority} onChange={e=>update("priority",e.target.value)}><option value="low">Baja</option><option value="medium">Media</option><option value="high">Alta</option></select></Field>{form.kind!=="milestone"&&<div className="grid grid-cols-[1fr_140px] gap-3"><Field label="Tiempo estimado"><input className="field" type="number" min="0" step="0.01" value={form.estimateValue} onChange={e=>update("estimateValue",e.target.value)}/></Field><Field label="Unidad"><select className="field" value={form.estimateUnit} onChange={e=>update("estimateUnit",e.target.value)}><option value="hours">Horas</option><option value="days">Días</option></select></Field></div>}</div><DependencyPicker tasks={tasks} projectId={form.projectId} taskId={form.id} selected={selectedDependencies} onChange={setSelectedDependencies}/>{selectedDependencies.length>0&&<p className="hint">{dependencyStart?`Inicio planificado calculado: ${fmt(dependencyStart)} (día siguiente al último fin planificado de las dependencias).`:"Todas las dependencias deben tener una fecha de fin planificada."}</p>}<DateFields form={form} update={update} planned lockedStart={selectedDependencies.length>0}/>{modal==="taskManage"&&<><Field label="Motivo de reprogramación (si cambias las fechas)"><textarea className="field min-h-16" value={form.reason} onChange={e=>update("reason",e.target.value)} placeholder="Explica el cambio de cronograma"/></Field><History items={data.reschedules.filter(r=>r.task_id===form.id)} users={users}/></>}</>}
        {modal==="progress"&&<><DependencyNotice names={data.dependencies.filter(d=>d.task_id===form.id).map(d=>data.dependencyTasks.find(t=>t.id===d.depends_on_id)).filter((t):t is DependencySummary=>!!t&&t.status!=="done").map(t=>t.title)}/><Field label="Estado"><select className="field" value={form.status} onChange={e=>update("status",e.target.value)}>{["todo","progress","review","done"].map(s=><option key={s} value={s}>{statuses[s]}</option>)}</select></Field><Field label={`Avance: ${form.status==="done"?100:form.progress}%`}><input className="w-full accent-[#2d7eb4]" type="range" min="0" max="100" step="5" value={form.status==="done"?100:form.progress} onChange={e=>update("progress",e.target.value)}/></Field><DateFields form={form} update={update}/><p className="hint">Las fechas reales registran la ejecución; las planificadas se cambian desde la edición de la actividad.</p><History items={data.reschedules.filter(r=>r.task_id===form.id)} users={users}/></>}
        {modal==="member"&&<><Field label="Nombre completo *"><input className="field" required value={form.name} onChange={e=>update("name",e.target.value)}/></Field><Field label="Correo electrónico *"><input className="field" type="email" required value={form.email} onChange={e=>update("email",e.target.value)}/></Field><Field label="Rol"><select className="field" value={form.role} onChange={e=>update("role",e.target.value)}><option value="staff">Personal</option><option value="coordinator">Coordinador</option></select></Field></>}
        {modal==="assign"&&<Field label="Integrante"><select className="field" required value={form.userId} onChange={e=>update("userId",e.target.value)}><option value="">Selecciona una persona</option>{users.map(u=><option key={u.id} value={u.id}>{u.name}</option>)}</select></Field>}
        {error&&<Notice text={error}/>}<div className="flex justify-end gap-3 border-t border-[#e6eef5] pt-5"><button type="button" className="secondary-btn" onClick={()=>setModal(null)}>Cancelar</button><button className="primary-btn" type="submit" disabled={saving}>{saving?"Guardando…":"Guardar"}</button></div>
      </form></div></div>}
  </div>;
}

function Avatar({name}:{name:string}){return <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-[#cfe6f6] text-xs font-bold text-[#286996]">{initials(name)}</span>}
function Heading({eyebrow,title,subtitle,action,actionText}:{eyebrow:string;title:string;subtitle:string;action?:()=>void;actionText:string}){return <div className="mb-8 flex flex-wrap items-end justify-between gap-4"><div><p className="mb-2 text-xs font-bold uppercase tracking-[.2em] text-[#4387b4]">{eyebrow}</p><h1 className="text-3xl font-bold tracking-tight text-[#133a5c]">{title}</h1><p className="mt-2 text-sm text-[#7896ac]">{subtitle}</p></div>{action&&<button className="primary-btn" onClick={action}><Plus size={16}/>{actionText}</button>}</div>}
function Field({label,children}:{label:string;children:React.ReactNode}){return <label className="block"><span className="mb-1.5 block text-xs font-semibold text-[#3f617b]">{label}</span>{children}</label>}
function DateFields({form,update,planned=false,lockedStart=false}:{form:Record<string,string>;update:(k:string,v:string)=>void;planned?:boolean;lockedStart?:boolean}){return <div className="grid grid-cols-2 gap-3"><Field label={planned?"Inicio planificado *":"Inicio real"}><input className="field" type="date" required={planned} readOnly={lockedStart} value={form[planned?"plannedStart":"actualStart"]} onChange={e=>update(planned?"plannedStart":"actualStart",e.target.value)}/></Field><Field label={planned?"Fin planificado *":"Fin real"}><input className="field" type="date" required={planned} value={form[planned?"plannedEnd":"actualEnd"]} onChange={e=>update(planned?"plannedEnd":"actualEnd",e.target.value)}/></Field></div>}
function SearchBox({value,onChange,placeholder}:{value:string;onChange:(v:string)=>void;placeholder:string}){return <div className="search-box"><Search size={15}/><input value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder}/></div>}
function ProjectStatus({value}:{value:string}){const item=projectStatuses[normalizeProjectStatus(value)]||projectStatuses.pending;return <span className={`rounded-full px-2.5 py-1 text-[10px] font-bold ${item.style}`}>{item.label}</span>}
function Status({value}:{value:string}){return <span className="rounded-full bg-[#e8f2fa] px-2.5 py-1 text-[10px] font-semibold text-[#3479a6]">{statuses[value]||value}</span>}
function Empty({text}:{text:string}){return <div className="rounded-2xl border border-dashed border-[#cddfec] bg-white px-6 py-12 text-center text-sm text-[#91a9ba]"><FolderKanban className="mx-auto mb-3 text-[#b6d0e2]" size={27}/>{text}</div>}
function Info({label,value}:{label:string;value:string}){return <div className="panel p-5"><p className="mb-2 text-xs font-medium text-[#8ba5ba]">{label}</p><p className="whitespace-pre-wrap text-sm font-semibold leading-6 text-[#214968]">{value}</p></div>}
function Notice({text}:{text:string}){return <p role="alert" className="rounded-xl border border-red-200 bg-red-50 p-3 text-xs text-red-600">{text}</p>}
function ProjectCards({items,progress,groups,openProject}:{items:Project[];progress:(id:string)=>number;groups:{id:string;name:string}[];openProject:(id:string)=>void}){return <div className="grid gap-4 md:grid-cols-2 2xl:grid-cols-3">{items.map(p=><button key={p.id} onClick={()=>openProject(p.id)} className="panel p-5 text-left transition hover:border-[#90bddb] hover:shadow-md"><div className="flex items-start justify-between gap-3"><h3 className="min-w-0 flex-1 text-base font-bold text-[#153e61]">{p.name}</h3><ProjectStatus value={p.status}/></div><div className="mt-6 flex items-center justify-between text-xs"><span className="text-[#7896ac]">Avance</span><strong className="text-[#2e79ac]">{progress(p.id)}%</strong></div><div className="mt-2 h-1.5 rounded-full bg-[#e8f2f9]"><div className="h-full rounded-full bg-[#3c91c8]" style={{width:`${progress(p.id)}%`}}/></div><p className="mt-5 border-t border-[#edf3f8] pt-4 text-xs text-[#6789a2]">Grupo: <strong className="font-semibold text-[#315f81]">{groups.find(g=>g.id===p.group_id)?.name||"Sin grupo"}</strong></p></button>)}</div>}
function DependencyPicker({tasks,projectId,taskId,selected,onChange}:{tasks:Task[];projectId:string;taskId:string;selected:string[];onChange:(ids:string[])=>void}){
  const options=tasks.filter(t=>t.project_id===projectId&&t.id!==taskId);
  return <div><p className="mb-2 text-xs font-semibold text-[#3f617b]">Depende de <span className="font-normal text-[#8aa6ba]">(opcional)</span></p>
    {options.length?<div className="max-h-40 overflow-auto rounded-xl border border-[#dce8f1] p-3">{options.map(task=><label key={task.id} className="flex cursor-pointer items-center gap-2 rounded-lg px-2 py-1.5 text-xs hover:bg-[#f2f8fc]"><input type="checkbox" checked={selected.includes(task.id)} onChange={e=>onChange(e.target.checked?[...selected,task.id]:selected.filter(id=>id!==task.id))} className="accent-[#2d7eb4]"/><span className="min-w-0 flex-1 truncate">{task.title}</span><span className="text-[#8aa6ba]">{statuses[task.status]}</span></label>)}</div>:<p className="rounded-xl bg-[#f3f8fc] p-3 text-xs text-[#8aa6ba]">No hay otras actividades en este proyecto.</p>}
    <p className="mt-2 text-[11px] text-[#7c9ab0]">Esta actividad podrá iniciarse cuando se completen todas sus predecesoras.</p>
  </div>;
}
function DependencyNotice({names}:{names:string[]}){return names.length?<div className="flex gap-2 rounded-xl border border-[#cce1f0] bg-[#eef7fc] p-3 text-xs text-[#2d6d9b]"><Clock3 size={16} className="shrink-0"/><span><strong>Actividad bloqueada.</strong> Completa primero: {names.join(", ")}.</span></div>:null}
function TaskList({items,projects,stages,assigneeNames,openTask,isCoordinator,blockers}:{items:Task[];projects:Project[];stages:Stage[];assigneeNames:(t:Task)=>string;openTask:(t:Task,manage?:boolean)=>void;isCoordinator:boolean|undefined;blockers:(t:Task)=>DependencySummary[]}){
  if(!items.length)return <Empty text="Aún no hay actividades"/>;
  return <div className="panel overflow-x-auto"><table className="w-full min-w-[850px] text-left"><thead><tr className="border-b border-[#e8f0f6] text-[11px] font-bold uppercase tracking-wider text-[#8ba5ba]"><th className="px-5 py-4">Actividad</th><th className="px-4 py-4">Responsables</th><th className="px-4 py-4">Planificado</th><th className="px-4 py-4">Real</th><th className="px-4 py-4">Avance</th><th className="px-4 py-4">Estado</th><th className="px-4 py-4"></th></tr></thead>
    <tbody>{items.map(t=>{const pending=blockers(t);return <tr key={t.id} className="border-b border-[#edf3f8] last:border-0 hover:bg-[#f8fbfe]"><td className="px-5 py-4"><div className="flex items-center gap-2"><strong className="text-sm">{t.title}</strong>{t.kind==="milestone"&&<span className="rounded bg-[#dceefa] px-1.5 py-0.5 text-[10px] font-bold text-[#3276a5]">HITO</span>}</div><small className="mt-1 block text-[#91a9bb]">{projects.find(p=>p.id===t.project_id)?.name}{stages.find(s=>s.id===t.stage_id)?.name?` · ${stages.find(s=>s.id===t.stage_id)?.name}`:""}{t.kind!=="milestone"?` · ${estimateLabel(t)}`:""}</small>{pending.length>0&&<span className="mt-1 block text-[11px] font-semibold text-[#2c74a4]" title={`Pendiente: ${pending.map(x=>x.title).join(", ")}`}><Clock3 size={12} className="mr-1 inline"/>Bloqueada: {pending.map(x=>x.title).join(", ")}</span>}{delayed(t)&&<span className="mt-1 inline-flex items-center gap-1 text-[11px] font-semibold text-[#bd5959]"><AlertTriangle size={12}/> Retrasada</span>}</td><td className="max-w-[170px] px-4 py-4 text-xs text-[#63849c]">{assigneeNames(t)}</td><td className="px-4 py-4 text-xs text-[#63849c]">{fmt(t.planned_start)}<br/>{fmt(t.planned_end)}</td><td className="px-4 py-4 text-xs text-[#63849c]">{fmt(t.actual_start)}<br/>{fmt(t.actual_end)}</td><td className="px-4 py-4"><strong className="text-xs text-[#3778a6]">{t.progress}%</strong><div className="mt-1 h-1.5 w-20 rounded-full bg-[#e6f1f8]"><div className="h-full rounded-full bg-[#3c91c8]" style={{width:`${t.progress}%`}}/></div></td><td className="px-4 py-4"><Status value={t.status}/></td><td className="px-4 py-4"><div className="flex gap-1"><button onClick={()=>openTask(t)} className="rounded-lg p-2 text-[#397faf] hover:bg-[#eaf4fa]" title="Actualizar avance" aria-label={`Actualizar avance de ${t.title}`}><Target size={16}/></button>{isCoordinator&&<button onClick={()=>openTask(t,true)} className="rounded-lg p-2 text-[#397faf] hover:bg-[#eaf4fa]" title="Editar y reprogramar" aria-label={`Editar ${t.title}`}><Pencil size={16}/></button>}</div></td></tr>})}</tbody></table></div>;
}
function History({items,users}:{items:Reschedule[];users:User[]}){return <div className="rounded-xl border border-[#e2edf4] bg-[#f8fbfe] p-4"><h3 className="mb-3 flex items-center gap-2 text-xs font-bold text-[#315f81]"><ClipboardList size={15}/> Historial de reprogramación</h3>{items.length?<div className="max-h-40 space-y-3 overflow-auto">{items.map(r=><div key={r.id} className="border-l-2 border-[#8bbddd] pl-3 text-[11px] text-[#5e7e96]"><strong>{fmt(r.old_start)} – {fmt(r.old_end)} → {fmt(r.new_start)} – {fmt(r.new_end)}</strong><p>{r.reason}</p><p className="text-[#96adbd]">{users.find(u=>u.id===r.changed_by)?.name||"Coordinador"} · {new Date(r.created_at).toLocaleString("es-PE")}</p></div>)}</div>:<p className="text-[11px] text-[#9bb0c0]">Aún no hay reprogramaciones.</p>}</div>}
